package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

public class SavePerson {
    public void save(@Val Person person, PersonStore store) throws StalePersonException {
        // Stored only over the version loaded, so a save racing this one cannot be overwritten.
        if (!store.save(person)) {
            throw new StalePersonException();
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class SavePersonAdded {
    public void save(@PathVariable("sheetId") String sheetId, @Val PersonRequest request, PersonStore store,
            Out<Person> person) {
        person.set(store.add(sheetId.trim(), request.name(), request.grade()));
    }
}
package net.officefloor.hq.app.person;

import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.statement.StatementStore;
import net.officefloor.hq.app.statement.StatementSummary;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class RespondWithPeople {
    public void respond(@PathVariable("sheetId") String sheetId, PersonStore store,
            StatementStore statements, PatronStore patrons, ObjectResponse<List<PersonResponse>> response) {
        Map<Long, StatementSummary> stated = statements.summaries(sheetId.trim());
        Map<Long, List<Long>> named = patrons.all(sheetId.trim());
        response.send(store.list(sheetId.trim()).stream()
                .map(p -> PersonResponse.from(p, stated.getOrDefault(p.getId(), StatementSummary.NONE),
                        named.getOrDefault(p.getId(), List.of())))
                .toList());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.statement.StatementStore;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Person person, StatementStore statements, PatronStore patrons,
            ObjectResponse<PersonResponse> response) {
        response.send(PersonResponse.from(person, statements.summary(person.getSheetId(), person.getId()),
                patrons.of(person.getSheetId(), person.getId())));
    }
}
